var autoSaveInput = (typeof autoSave !== "undefined") ? autoSave : null;
if ((autoSaveInput === null || autoSaveInput === undefined) && typeof commit !== "undefined") {
  autoSaveInput = commit;
}
var autoSaveFlag = C8O.util.parseAutoSaveFlag(autoSaveInput, true);
var refreshInput = (typeof refresh !== "undefined") ? refresh : true;
var refreshFlag = C8O.util.toBoolean(refreshInput, true) === true;
var optimizeMutationsInput = (typeof optimizeMutations !== "undefined") ? optimizeMutations : false;
var optimizeMutationsFlag = C8O.util.toBoolean(optimizeMutationsInput, false) === true;
if (optimizeMutationsFlag) {
  autoSaveFlag = false;
  refreshFlag = false;
}

var moveResult = C8O.dbo.moveObject({ qname: qname, target: target, position: position });

var classNameText = moveResult.className ? String(moveResult.className) : "";
var qnameText = moveResult.qname ? String(moveResult.qname) : String(qname);
var nameText = moveResult.name ? String(moveResult.name) : "";
var fromParentText = moveResult.fromParent ? String(moveResult.fromParent) : "";
var toParentText = moveResult.toParent ? String(moveResult.toParent) : "";
var projectNameText = moveResult.projectName ? String(moveResult.projectName) : "";
var positionText = moveResult.position ? String(moveResult.position) : (position || "inside");
var afterValue = moveResult.after != null ? moveResult.after : null;

moveInfo = moveResult;
moveErrors = Array.isArray(moveResult.errors) ? moveResult.errors : [];
moveAutoSave = autoSaveFlag;
moveProject = moveResult.project || null;
moveSaved = false;
moveSaveMessage = "";
moveAutoSaveApplied = autoSaveFlag;
moveDone = Boolean(moveResult.done);
moveMoved = Boolean(moveResult.moved);
moveReordered = Boolean(moveResult.reordered);
moveClassName = classNameText;
moveQName = qnameText;
moveName = nameText;
moveFromParent = fromParentText;
moveToParent = toParentText;
movePosition = positionText;
moveAfter = afterValue;
moveProjectName = projectNameText;
moveShouldRefreshFrom = refreshFlag && moveDone && fromParentText.length > 0;
moveShouldRefreshTo = refreshFlag && moveDone && toParentText.length > 0 && toParentText !== fromParentText;
moveSummaryMoved = moveMoved ? 1 : 0;
moveSummaryReordered = moveReordered ? 1 : 0;
moveSummaryErrors = moveErrors.length;

var saveResult = C8O.dbo.saveProjectIfNeeded(moveProject, moveAutoSave, moveErrors);
var savedFlag = saveResult.saved === true;
moveSaved = savedFlag;
moveSaveMessage = saveResult.message || "";
moveAutoSaveApplied = moveAutoSave;
